def sha(p): return hashlib.sha256(Path(p).read_bytes()).hexdigest()
FORBID = {'.pt', '.pth', '.npz', '.pyc', '.ckpt', '.zip'}
files = sorted(p for p in PK.rglob('*') if p.is_file() and p.name != 'FILE_MANIFEST.md')
assert not [p for p in files if p.suffix in FORBID or '__pycache__' in str(p) or '.venv' in str(p)], 'forbidden file type in package'
cmap = dict(COPIES)
mrows = []
for p in files:
    rel = str(p.relative_to(PK)); src = cmap.get(rel)
    if src: assert sha(src) == sha(p), f'copy differs from source: {rel}'
    mrows.append(f"| `{rel}` | {p.stat().st_size:,} | `{sha(p)[:16]}` | {('unchanged copy of `' + src + '`') if src else 'generated for this package'} |")
W('11_SOURCE_INDEX/FILE_MANIFEST.md', f'''
# File manifest

{len(files)} files (this manifest excluded). SHA-256 shown truncated to 16 hex characters. "Unchanged copy" entries were byte-compared with their source at build time (hashes equal). No checkpoints (`.pt`), prediction arrays (`.npz`), caches, virtual environments or raw datasets are included.

| File | Bytes | SHA-256 (16) | Origin |
|---|---:|---|---|
''' + '\n'.join(mrows))
